    def __init__(self, init_data, init_next_node=None):
        self.__data = init_data
        self.__next = init_next_node

    def get_data(self):
        return self.__data

    def get_next(self):
        return self.__next

    def set_data(self, new_data):
        self.__data = new_data

    def set_next(self, new_next_node):
        self.__next = new_next_node

    def add_after(self, value):
        new_node = Node(value)
        temp = self.get_next()
        self.set_next(new_node)
        self.get_next().set_next(temp)

    def remove_after(self):
        current = self.get_next()
        previous = self
        previous.set_next(current.get_next())
        current.set_next(None)

    def __contains__(self, value):
        is_contains = False
        current = self.get_next()
        if value == self.get_data():
            is_contains = True
        else:
            while current != None:
                if value == current.get_data():
                    is_contains = True
                    return is_contains
                else:
                    current = current.get_next()
        return is_contains

    def __str__(self):
        return str(self.get_data())

    def get_sum(self):
        the_sum = self.get_data()
        current = self.__next
        while current != None:
            the_sum += current.get_data()
            current = current.get_next()
        return the_sum

